# (3.11.2026) כרגע רצים רק 2 קמפיינים – תזכורות "להעלות קמפיין" הופכות להמתנה, ובמקומן בדיקות מדידה
for _p in P:
    c = _p.get("camp", "")
    if c.startswith("להעלות קמפיין") or c.startswith("אם עוד לא – להעלות"): _p["camp"] = ""
    elif c.startswith("לבדוק את 4 הקמפיינים") or c.startswith("אפשרות (רק באישור שמש): בקמפיין 3"): _p["camp"] = ""
    elif c.startswith("שבוע ראשון עבר"): _p["camp"] = "שבוע ראשון לשני הקמפיינים (גנים + קורס): בתוסף ← 📊 מדידה ← 7 ימים. כמה נכנסו מכל מודעה (🚪), כמה לחצו בעמוד הגנים / על הרשמה לקורס – ומול זה: כמה פניות והרשמות אמיתיות קיבלת. רק אז להחליט אם להגדיל, לשנות או להחזיר את חנוכה."
    elif c.startswith("סיכום חודש"): _p["camp"] = "סיכום חודש: כמה עלתה פנייה אמיתית של גן וכמה עלתה הרשמה לקורס? אם משתלם – להגדיל; אם לא – לשנות מודעה או עמוד."

# ===================== כלל קבוע (שמש, 3.11.2026): בכל הודעה לקבוצות וואטסאפ – "עזרו לנו לגדול" =====================
GROW = "🙏 *עזרו לנו לגדול – הזמינו חברים לקבוצה* 💕"
def add_grow(txt):
    if not txt or "עזרו לנו לגדול" in txt: return txt
    return txt.rstrip() + "\n\n" + GROW + ("" if "{GROUP}" in txt else "\n{GROUP}")
for _t in T:
    for _k in ("wa", "share"):
        if _t.get(_k): _t[_k] = add_grow(_t[_k])

